import * as React from "react";

export type LaptopIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function LaptopIcon({ size = 20, ...props }: LaptopIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <path d="M6 6 L18 6 L18 15 L6 15 Z" /><path d="M3.5 18 L20.5 18 L19 15 L5 15 Z" />
    </svg>
  );
}
